        if len(val) == 2:  # tau15 -> 0.15
            return int(val) / 100.0
        elif len(val) == 3:  # tau015 -> 0.15, tau025 -> 0.25
            return int(val) / 1000.0
        elif len(val) == 4:  # tau0075 -> 0.075
            return int(val) / 10000.0
        else:
            return int(val) / (10 ** len(val))
    return None

