    if "adapt" in eid_lower or "adaptive" in eid_lower:
        return "adaptive"
    if "k2mean" in eid_lower:
        return "k2-mean"
    if "k10" in eid_lower:
        return "k10"
    if "k2" in eid_lower:
        return "k2"

    # Check command for mode
    if "adaptive" in cmd or "adapt" in cmd:
        return "adaptive"
    if "always" in cmd:
        return "always-on"

    # tau-sweep experiments - check command
    if "tau-sweep" in eid_lower or "tau_sweep" in eid_lower:
        if "adaptive_conformal" in cmd or "adaptive" in cmd:
            return "adaptive"
        if "k2" in cmd:
            return "k2"

    return "unknown"

