    vla = extract_vla(eid)
    method = extract_method(eid, spec)

    if suite is None or vla is None:
        # Try to infer VLA from command
        cmd = spec.get("command", "")
        if "smolvla" in cmd.lower():
            vla = "smolvla"
        elif "pi05" in cmd.lower() or "pi0" in cmd.lower():
            vla = "pi05"

