        continue

    rows.append({
        "exp_id": eid,
        "tau": tau,
        "trigger_rate": tr,
        "success_rate": sr,
        "suite": suite,
        "vla": vla,
        "method": method,
        "conclusion": exp.get("conclusion", ""),
        "baseline_sr": metrics.get("baseline_vla_only_sr", None),
        "delta": metrics.get("delta_vs_baseline", None),
    })

print(f"Total rows with tau + trigger_rate + success_rate: {len(rows)}")
print()

# Save to JSON for further analysis
with open("/tmp/tau_sweep_data.json", "w") as f:
    json.dump(rows, f, indent=2)

# Group by suite x VLA x method
groups = defaultdict(list)
for r in rows:
    key = (r["suite"], r["vla"], r["method"])
    groups[key].append(r)

# Sort each group by tau
for key in groups:
    groups[key].sort(key=lambda x: x["tau"])

# Print summary of groups
print("Groups (suite × VLA × method):")
print(f"{'Suite':<10} {'VLA':<10} {'Method':<12} {'Count':<6} {'Tau range'}")
print("-" * 60)
for key in sorted(groups.keys()):
    items = groups[key]
    taus = [x["tau"] for x in items]
    print(f"{key[0]:<10} {key[1]:<10} {key[2]:<12} {len(items):<6} {min(taus):.3f} - {max(taus):.3f}")

