import json, re
from collections import defaultdict

DATAFILE = "/home/ubuntu/.claude-account-3/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-8-projects-acr-vla-conformal-refinement--claude-sessions-reviewer-4966e04b/9621b5e7-de47-404e-af6e-a0f6f9da2346/tool-results/mcp-agent-ml-research-read_registry-1779948496951.txt"
with open(DATAFILE) as f:
    raw = json.load(f)
data = json.loads(raw["result"])
experiments = data["data"]["experiments"]

def normalize_to_pct(val, rollouts=None, successes=None):
    """Normalize to percentage [0, 100]. Use rollout data if available."""
    if val is None:
        return None
    val = float(val)
    # If we have rollout data, compute directly
    if rollouts is not None and successes is not None and rollouts > 0:
        return successes / rollouts * 100.0
    # Heuristic: if val <= 1.0, likely fraction
    if val <= 1.0:
        return val * 100.0
    return val

def extract_tau_from_cmd(cmd):
    """Extract conformal_threshold from command string."""
    m = re.search(r'conformal_threshold\s+([0-9.]+)', cmd)
    if m:
        return float(m.group(1))
    return None

def extract_tau(eid, metrics, spec):
    # First: from command (most reliable)
    cmd = (spec or {}).get("command", "")
    tau_cmd = extract_tau_from_cmd(cmd)
    if tau_cmd is not None:
        return tau_cmd
    # From metrics
    if metrics and "tau" in metrics:
        return float(metrics["tau"])
    if metrics and "conformal_threshold" in metrics:
        return float(metrics["conformal_threshold"])
    # From exp_id (as fallback)
    m = re.search(r'tau(\d+)', eid)
    if m:
        val = m.group(1)
        if len(val) <= 3:
            return int(val) / 1000.0 if len(val) == 3 else int(val) / 100.0
        else:
            return int(val) / 10000.0
    return None

def extract_suite(eid):
    eid_lower = eid.lower()
    for s in ["spatial", "object", "goal", "long"]:
        if s in eid_lower:
            return s
    if "obj" in eid_lower:
        return "object"
    return None

def extract_vla(eid, spec):
    eid_lower = eid.lower()
    cmd = (spec or {}).get("command", "").lower()
    if "pi05" in eid_lower or "pi0" in eid_lower or "pi05" in cmd:
        return "pi05"
    if "smolvla" in eid_lower or "smolvla" in cmd:
        return "smolvla"
    return None

def extract_method(eid, spec):
    eid_lower = eid.lower()
    cmd = (spec or {}).get("command", "").lower()
    if "vla-only" in eid_lower or "vla_only" in eid_lower or "--mode vla_only" in cmd:
        return "vla-only"
    if "always-on" in eid_lower or "always_on" in eid_lower or "crm-always" in eid_lower:
        return "always-on"
    if "adapt" in eid_lower or "adaptive" in eid_lower or "adaptive_conformal" in cmd:
        return "adaptive"
    if "k2mean" in eid_lower:
        return "k2-mean"
    if "k10" in eid_lower:
        return "k10"
    if "k2" in eid_lower:
        return "k2"
    return "unknown"

# Collect all experiments
rows = []
for eid, exp in experiments.items():
    metrics = exp.get("metrics", {}) or {}
    spec = exp.get("spec", {}) or {}

    sr_raw = metrics.get("success_rate")
    tr_raw = metrics.get("trigger_rate")
    if sr_raw is None or tr_raw is None:
        continue

    rollouts = metrics.get("total_rollouts")
    successes = metrics.get("total_successes")

    sr = normalize_to_pct(sr_raw, rollouts, successes)
    # For trigger_rate, normalize similarly (but no rollout-based correction available)
    tr = normalize_to_pct(tr_raw)

    tau = extract_tau(eid, metrics, spec)
    if tau is None:
        continue

    suite = extract_suite(eid)
    vla = extract_vla(eid, spec)
    method = extract_method(eid, spec)

    if suite is None or vla is None:
        continue

    # Extract seed
    sm = re.search(r's(\d+)', eid)
    seed = int(sm.group(1)) if sm else None

    rows.append({
        "exp_id": eid,
        "tau": tau,
        "trigger_rate": round(tr, 2),
        "success_rate": round(sr, 2),
        "suite": suite,
        "vla": vla,
        "method": method,
        "seed": seed,
        "sr_raw": sr_raw,
        "tr_raw": tr_raw,
    })

# Group by (suite, vla, method) -> only adaptive for tau sweep
groups = defaultdict(list)
for r in rows:
    key = (r["suite"], r["vla"], r["method"])
    groups[key].append(r)

# Aggregate by tau (average across seeds)
def aggregate_by_tau(items):
    by_tau = defaultdict(list)
    for item in items:
        by_tau[item["tau"]].append(item)

    result = []
    for tau_val in sorted(by_tau.keys()):
        entries = by_tau[tau_val]
        avg_tr = sum(e["trigger_rate"] for e in entries) / len(entries)
        avg_sr = sum(e["success_rate"] for e in entries) / len(entries)
        std_sr = (sum((e["success_rate"] - avg_sr)**2 for e in entries) / max(len(entries)-1, 1))**0.5 if len(entries) > 1 else 0
        std_tr = (sum((e["trigger_rate"] - avg_tr)**2 for e in entries) / max(len(entries)-1, 1))**0.5 if len(entries) > 1 else 0
        seeds = sorted(set(e["seed"] for e in entries if e["seed"]))
        eids = [e["exp_id"] for e in entries]
        result.append({
            "tau": tau_val,
            "trigger_rate": round(avg_tr, 1),
            "success_rate": round(avg_sr, 1),
            "std_sr": round(std_sr, 1),
            "std_tr": round(std_tr, 1),
            "n": len(entries),
            "seeds": seeds,
            "exp_ids": eids,
        })
    return result

def check_monotonicity(agg_data, field):
    violations = []
    for i in range(1, len(agg_data)):
        prev = agg_data[i-1]
        curr = agg_data[i]
        if curr[field] > prev[field] + 0.5:  # Allow 0.5% tolerance for noise
            violations.append({
                "tau_from": prev["tau"],
                "tau_to": curr["tau"],
                "val_from": prev[field],
                "val_to": curr[field],
                "delta": round(curr[field] - prev[field], 1),
            })
    return violations

suites_order = ["object", "spatial", "goal", "long"]
vla_order = ["smolvla", "pi05"]

all_violations = []

for suite in suites_order:
    header_printed = False
    for vla in vla_order:
        for method in ["adaptive", "k2", "k10"]:
            key = (suite, vla, method)
            if key not in groups:
                continue
            items = groups[key]
            agg = aggregate_by_tau(items)
            if len(agg) < 2:
                continue

            if not header_printed:
                print(f"\n{'='*110}")
                print(f"  SUITE: {suite.upper()}")
                print(f"{'='*110}")
                header_printed = True

            print(f"\n--- {vla} / {method} ({len(items)} exps → {len(agg)} tau points) ---")
            print(f"{'tau':>8} | {'TR%':>8} {'±':>4} | {'SR%':>8} {'±':>4} | {'n':>3} | {'Experiments'}")
            print(f"{'-'*8}-+-{'-'*8}-{'-'*4}-+-{'-'*8}-{'-'*4}-+-{'-'*3}-+-{'-'*50}")

            for a in agg:
                std_tr_str = f"±{a['std_tr']:.0f}" if a["n"] > 1 else ""
                std_sr_str = f"±{a['std_sr']:.0f}" if a["n"] > 1 else ""
                eids_short = ", ".join(e.split("/")[-1][:30] for e in a["exp_ids"][:2])
                if a["n"] > 2:
                    eids_short += f" +{a['n']-2}more"
                print(f"{a['tau']:>8.3f} | {a['trigger_rate']:>8.1f} {std_tr_str:>4} | {a['success_rate']:>8.1f} {std_sr_str:>4} | {a['n']:>3} | {eids_short}")

            tr_viol = check_monotonicity(agg, "trigger_rate")
            if tr_viol:
                print(f"\n  *** TR NON-MONOTONIC ({len(tr_viol)} violations):")
                for v in tr_viol:
                    print(f"      tau {v['tau_from']:.3f} → {v['tau_to']:.3f}: TR {v['val_from']:.1f}% → {v['val_to']:.1f}% (+{v['delta']:.1f}pp)")
                    all_violations.append((suite, vla, method, v))
            else:
                print(f"\n  TR: MONOTONICALLY DECREASING as tau increases")

print(f"\n\n{'='*110}")
print(f"  MONOTONICITY VERDICT")
print(f"{'='*110}")

# Recount
total = 0
mono = 0
for suite in suites_order:
    for vla in vla_order:
        for method in ["adaptive", "k2", "k10"]:
            key = (suite, vla, method)
            if key not in groups:
                continue
            agg = aggregate_by_tau(groups[key])
            if len(agg) < 2:
                continue
            total += 1
            tr_viol = check_monotonicity(agg, "trigger_rate")
            status = "MONOTONIC" if not tr_viol else f"NON-MONOTONIC ({len(tr_viol)}v)"
            if not tr_viol:
                mono += 1
            n_pts = len(agg)
            print(f"  {suite:<10} {vla:<10} {method:<12} {n_pts:>3} tau pts  {status}")

print(f"\n  Result: {mono}/{total} groups strictly monotonic (with ±0.5pp tolerance)")
print(f"  Total TR violations: {len(all_violations)}")

if all_violations:
    print(f"\n  All violations:")
    for suite, vla, method, v in all_violations:
        print(f"    {suite}/{vla}/{method}: tau {v['tau_from']:.3f}→{v['tau_to']:.3f}: TR {v['val_from']:.1f}→{v['val_to']:.1f} (+{v['delta']:.1f}pp)")

# Check: within violations, how many involve high-std groups?
print(f"\n{'='*110}")
print(f"  VIOLATION ROOT CAUSE ANALYSIS")
print(f"{'='*110}")
for suite, vla, method, v in all_violations:
    key = (suite, vla, method)
    agg = aggregate_by_tau(groups[key])
    # Find the two tau points
    for a in agg:
        if abs(a["tau"] - v["tau_from"]) < 0.001 or abs(a["tau"] - v["tau_to"]) < 0.001:
            if a["std_tr"] > 0:
                print(f"  {suite}/{vla}/{method} tau={a['tau']:.3f}: TR={a['trigger_rate']:.1f}±{a['std_tr']:.1f} (n={a['n']}, seeds={a['seeds']})")
                # Show individual experiments
                for eid in a["exp_ids"]:
                    for r in groups[key]:
                        if r["exp_id"] == eid:
                            print(f"    {eid}: TR={r['trigger_rate']}, SR={r['success_rate']}, raw_sr={r['sr_raw']}, raw_tr={r['tr_raw']}")
            else:
                print(f"  {suite}/{vla}/{method} tau={a['tau']:.3f}: TR={a['trigger_rate']:.1f} (n=1)")

